package com.example.starter.mvi

import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import kotlinx.coroutines.ensureActive
import kotlin.coroutines.AbstractCoroutineContextElement
import kotlin.coroutines.CoroutineContext
import kotlin.coroutines.coroutineContext

/** Effects go to at most one consumer. ActiveOnly drops effects unless a consumer is ready
 * to receive; a slow consumer may therefore miss effects. Queued retains effects in memory
 * until consumed or the store is closed, so use it only for bounded event streams. A
 * collector cancelled after receiving an effect can still lose that effect. Closing the
 * store cancels the effect flow and discards buffered effects and intents.
 */
enum class EffectDelivery { ActiveOnly, Queued }

private class CommandOrder(val value: Long) : AbstractCoroutineContextElement(Key) {
    companion object Key : CoroutineContext.Key<CommandOrder>
}

data class Transition<S, E, C>(
    val state: S,
    val effects: List<E> = emptyList(),
    val commands: List<C> = emptyList(),
)

/** Serializes reductions while allowing commands to execute independently.
 * The owner must call [close] when its screen is disposed.
 */
abstract class MviStore<S, I, E, C>(
    initialState: S,
    parentScope: CoroutineScope,
    delivery: EffectDelivery = EffectDelivery.ActiveOnly,
) {
    private val job = SupervisorJob(parentScope.coroutineContext[Job])
    private val scope = CoroutineScope(parentScope.coroutineContext + job)
    private val intents = Channel<I>(Channel.UNLIMITED)
    private val workMutex = Mutex()
    private val keyedWork = mutableMapOf<String, Job>()
    private val latestOrder = mutableMapOf<String, Long>()
    private var commandOrder = 0L // Accessed only by the intent processor.
    private val mutableState = MutableStateFlow(initialState)
    val state: StateFlow<S> = mutableState.asStateFlow()
    private val activeEffects = Channel<E>(Channel.RENDEZVOUS)
    private val queuedEffects = Channel<E>(Channel.UNLIMITED)
    private val queueEffects = delivery == EffectDelivery.Queued
    val effects: Flow<E> = if (queueEffects) queuedEffects.receiveAsFlow() else activeEffects.receiveAsFlow()

    init {
        val processor = scope.launch {
            for (intent in intents) {
                try {
                    coroutineContext.ensureActive()
                    val update = reduce(mutableState.value, intent)
                    coroutineContext.ensureActive()
                    mutableState.value = update.state
                    update.effects.forEach {
                        if (queueEffects) queuedEffects.send(it) else activeEffects.trySend(it)
                    }
                    update.commands.forEach { command ->
                        val order = ++commandOrder
                        scope.launch(CommandOrder(order)) {
                            try {
                                execute(command)
                            } catch (error: CancellationException) {
                                throw error
                            } catch (error: Exception) {
                                onError(error)
                            }
                        }
                    }
                } catch (error: CancellationException) {
                    throw error
                } catch (error: Exception) {
                    onError(error)
                }
            }
        }
        // A failed or cancelled processor cannot accept further work. Cancel its sibling
        // commands as well, even when the parent scope was cancelled without calling close().
        processor.invokeOnCompletion {
            intents.cancel()
            activeEffects.cancel()
            queuedEffects.cancel()
            job.cancel()
        }
    }

    fun dispatch(intent: I): Boolean = job.isActive && intents.trySend(intent).isSuccess

    protected abstract fun reduce(state: S, intent: I): Transition<S, E, C>
    protected abstract suspend fun execute(command: C)
    protected abstract fun onError(error: Throwable)

    /** Opt in from execute: the latest dispatched command for a key supersedes older work,
     * even if coroutine scheduling reverses registration order. Commands must cooperate
     * with cancellation and guard against non-cooperative work returning stale results.
     */
    protected suspend fun replaceWork(key: String, block: suspend () -> Unit) {
        val current = checkNotNull(coroutineContext[Job])
        val order = checkNotNull(coroutineContext[CommandOrder]) { "replaceWork must be called from execute" }.value
        workMutex.withLock {
            if (order < (latestOrder[key] ?: Long.MIN_VALUE)) throw CancellationException("Superseded work")
            latestOrder[key] = order
            val previous = keyedWork.put(key, current)
            if (previous !== current) previous?.cancel()
        }
        try {
            block()
        } finally {
            withContext(NonCancellable) {
                workMutex.withLock { if (keyedWork[key] === current) keyedWork.remove(key) }
            }
        }
    }

    protected suspend fun cancelWork(key: String) {
        val order = checkNotNull(coroutineContext[CommandOrder]) { "cancelWork must be called from execute" }.value
        workMutex.withLock {
            if (order >= (latestOrder[key] ?: Long.MIN_VALUE)) {
                latestOrder[key] = order
                keyedWork.remove(key)?.cancel()
            }
        }
    }

    fun close() {
        job.cancel()
        intents.cancel()
        activeEffects.cancel()
        queuedEffects.cancel()
    }
}
