package com.example.starter.counter

import com.example.starter.mvi.MviStore
import com.example.starter.mvi.Transition
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.delay

data class CounterState(val count: Int = 0, val loading: Boolean = false, val error: Boolean = false)
sealed interface CounterIntent {
    data object Increment : CounterIntent
    data object Load : CounterIntent
    data object Failed : CounterIntent
    data object Loaded : CounterIntent
}
sealed interface CounterCommand { data class SimulateRequest(val succeeds: Boolean) : CounterCommand }

class CounterStore(scope: CoroutineScope) : MviStore<CounterState, CounterIntent, String, CounterCommand>(CounterState(), scope) {
    override fun reduce(state: CounterState, intent: CounterIntent): Transition<CounterState, String, CounterCommand> = when (intent) {
        CounterIntent.Increment -> Transition(state.copy(count = state.count + 1), effects = listOf("counter_updated"))
        CounterIntent.Load -> if (state.loading) Transition(state) else Transition(state.copy(loading = true, error = false), commands = listOf(CounterCommand.SimulateRequest(succeeds = state.error)))
        CounterIntent.Failed -> Transition(state.copy(loading = false, error = true))
        CounterIntent.Loaded -> Transition(state.copy(loading = false, error = false), effects = listOf("request_completed"))
    }
    override suspend fun execute(command: CounterCommand) {
        delay(500)
        when (command) {
            is CounterCommand.SimulateRequest -> dispatch(if (command.succeeds) CounterIntent.Loaded else CounterIntent.Failed)
        }
    }
    override fun onError(error: Throwable) { dispatch(CounterIntent.Failed) }
}
